// Рахуємо вікно вибірки: від останнього успішного запуску мінус нахлест.
// Стан живе у static data воркфлоу, тому переживає рестарт n8n.
const cfg = $('Конфіг').first().json;
const state = $getWorkflowStaticData('global');
const overlapMin = Number(cfg.overlapMinutes || 15);
const now = new Date();

let from;
if (state.lastSyncIso) {
  from = new Date(new Date(state.lastSyncIso).getTime() - overlapMin * 60000);
} else {
  // перший запуск — тягнемо за останні N днів (щоб не завантажити весь архів)
  from = new Date(now.getTime() - Number(cfg.firstRunDays || 7) * 86400000);
}

const fmt = (d) => d.toISOString().slice(0, 19).replace('T', ' ');

return [{
  json: {
    dateFrom: fmt(from),
    dateTo: fmt(now),
    dateFromIso: from.toISOString(),
    dateToIso: now.toISOString(),
    runStartedIso: now.toISOString(),
  },
}];

// Приводимо відповідь Realting до єдиної схеми.
// Формат відповіді наперед невідомий (кабінет закритий логіном), тому:
//  1) розгортаємо будь-яку обгортку-масив (data/items/orders/result/rows);
//  2) шукаємо поля за списком вірогідних назв;
//  3) весь оригінал кладемо в raw — нічого не губиться.
const state = $getWorkflowStaticData('global');
state.processedIds = state.processedIds || [];

const rows = [];
for (const item of $input.all()) {
  const j = item.json;
  if (Array.isArray(j)) { rows.push(...j); continue; }
  const arr = ['data', 'items', 'orders', 'result', 'rows', 'requests', 'leads']
    .map((k) => j && j[k])
    .find((v) => Array.isArray(v));
  if (arr) rows.push(...arr);
  else if (j && typeof j === 'object') rows.push(j);
}

const get = (obj, paths) => {
  for (const p of paths) {
    const v = p.split('.').reduce((a, c) => (a === null || a === undefined ? a : a[c]), obj);
    if (v !== undefined && v !== null && v !== '') return v;
  }
  return null;
};
const str = (v) => (v === null || v === undefined ? '' : String(v).trim());
const phoneClean = (v) => str(v).replace(/[^\d+]/g, '');

const out = [];
const skipped = [];

for (const r of rows) {
  const externalId = str(get(r, ['id', 'order_id', 'orderId', 'uuid', 'guid', 'number', 'request_id']));
  if (!externalId) { skipped.push({ reason: 'no_id', raw: r }); continue; }
  if (state.processedIds.includes(externalId)) { skipped.push({ reason: 'already_synced', id: externalId }); continue; }

  const phone = phoneClean(get(r, ['phone', 'phone_number', 'contact_phone', 'user.phone', 'client.phone', 'tel']));
  const email = str(get(r, ['email', 'contact_email', 'user.email', 'client.email'])).toLowerCase();
  if (!phone && !email) { skipped.push({ reason: 'no_contact', id: externalId, raw: r }); continue; }

  const fullName = str(get(r, ['name', 'full_name', 'fullName', 'contact_name', 'user.name', 'client.name', 'first_name']));
  const parts = fullName.split(/\s+/).filter(Boolean);

  out.push({
    json: {
      externalId,
      createdAt: str(get(r, ['created_at', 'createdAt', 'date', 'date_create', 'datetime', 'time'])),
      name: parts[0] || fullName,
      lastName: parts.slice(1).join(' '),
      fullName,
      phone,
      email,
      comment: str(get(r, ['message', 'comment', 'text', 'body', 'question', 'description'])),
      language: str(get(r, ['language', 'lang', 'locale'])),
      objectId: str(get(r, ['object_id', 'objectId', 'property_id', 'listing_id', 'ad_id'])),
      objectTitle: str(get(r, ['object_title', 'title', 'property', 'object.title', 'listing.title'])),
      objectUrl: str(get(r, ['object_url', 'url', 'link', 'object.url', 'listing.url'])),
      sourceType: str(get(r, ['type', 'order_type', 'form', 'source'])) || 'realting_order',
      utmSource: str(get(r, ['utm_source', 'utm.source'])),
      utmMedium: str(get(r, ['utm_medium', 'utm.medium'])),
      utmCampaign: str(get(r, ['utm_campaign', 'utm.campaign'])),
      raw: r,
    },
  });
}

if (skipped.length) {
  console.log('Realting sync: пропущено ' + skipped.length + ' записів', JSON.stringify(skipped).slice(0, 2000));
}

return out;

// Гілка "знайшли дубль": лишаємо слід у таймлайні існуючого ліда, нового не створюємо.
const out = [];
for (const item of $input.all()) {
  out.push({ json: { externalId: item.json.externalId, outcome: 'duplicate', bitrixLeadId: item.json.bitrixLeadId } });
}
return out;

// Збираємо тіло запиту для crm.lead.add.
const cfg = $('Конфіг').first().json;
const out = [];

for (const item of $input.all()) {
  const l = item.json;

  const commentLines = [
    l.comment ? 'Повідомлення: ' + l.comment : null,
    l.objectTitle ? 'Обʼєкт: ' + l.objectTitle : null,
    l.objectUrl ? 'Посилання: ' + l.objectUrl : null,
    l.objectId ? 'ID обʼєкта: ' + l.objectId : null,
    l.language ? 'Мова заявки: ' + l.language : null,
    l.createdAt ? 'Створено на Realting: ' + l.createdAt : null,
    'Realting ID: ' + l.externalId,
  ].filter(Boolean);

  const fields = {
    TITLE: 'Realting #' + l.externalId + (l.objectTitle ? ' — ' + l.objectTitle : ''),
    NAME: l.name || 'Без імені',
    LAST_NAME: l.lastName || '',
    SOURCE_ID: cfg.bitrixSourceId || 'WEB',
    SOURCE_DESCRIPTION: 'realting.com / ' + l.sourceType,
    COMMENTS: commentLines.join('\n'),
    ASSIGNED_BY_ID: cfg.assignedById,
    OPENED: 'Y',
    UTM_SOURCE: l.utmSource || 'realting.com',
    UTM_MEDIUM: l.utmMedium || 'referral',
    UTM_CAMPAIGN: l.utmCampaign || '',
  };

  if (cfg.externalIdField) fields[cfg.externalIdField] = l.externalId;
  if (l.phone) fields.PHONE = [{ VALUE: l.phone, VALUE_TYPE: 'WORK' }];
  if (l.email) fields.EMAIL = [{ VALUE: l.email, VALUE_TYPE: 'WORK' }];

  out.push({
    json: {
      externalId: l.externalId,
      payload: { fields, params: { REGISTER_SONET_EVENT: 'N' } },
    },
  });
}

return out;

// Фіксуємо стан: які заявки вже поїхали в Bitrix24 і до якого моменту синхронізовані.
const state = $getWorkflowStaticData('global');
state.processedIds = state.processedIds || [];

let created = 0;
let duplicates = 0;

for (const item of $input.all()) {
  const id = String(item.json.externalId || '');
  if (id && !state.processedIds.includes(id)) state.processedIds.push(id);
  if (item.json.outcome === 'duplicate') duplicates++;
  else created++;
}

// тримаємо тільки останні 5000 ID, щоб static data не розросталася
if (state.processedIds.length > 5000) {
  state.processedIds = state.processedIds.slice(-5000);
}

const win = $('Вікно синхронізації').first().json;
state.lastSyncIso = win.runStartedIso;

return [{ json: { syncedTo: state.lastSyncIso, created, duplicates, totalKnownIds: state.processedIds.length } }];
